-- Name: bump_tour_revision(); Type: FUNCTION; Schema: public; Owner: duongthanhhung
--

CREATE FUNCTION public.bump_tour_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tour_id UUID;
  v_row     RECORD;
BEGIN
  v_row := COALESCE(NEW, OLD);

  IF TG_TABLE_NAME = 'story' THEN
    v_tour_id := v_row.tour_id;
  ELSE
    SELECT s.tour_id INTO v_tour_id FROM story s WHERE s.id = v_row.story_id;
  END IF;

  IF v_tour_id IS NOT NULL THEN
    UPDATE tour SET revision = revision + 1, updated_at = now()
     WHERE id = v_tour_id;
  END IF;

  RETURN NULL;   -- AFTER trigger
END $$;


