--
-- TOC entry 238 (class 1259 OID 17454)
-- Name: v_tour_stop; Type: VIEW; Schema: public; Owner: duongthanhhung
--

CREATE VIEW public.v_tour_stop AS
 SELECT t.id AS tour_id,
    t.slug,
    t.locale,
    t.title AS tour_title,
    t.tagline,
    t.location_label,
    t.splash_image_url,
    t.ambient_audio_url,
    t.default_camera_clip_url,
    t.revision,
    t.published_at,
    s.id AS story_id,
    s.order_index,
    s.title AS scene_title,
    s.description AS scene_description,
    s.camera_clip_url,
    s.camera_name,
    s.clip_start_s,
    s.clip_end_s,
    s.start_camera_position,
    s.start_camera_target,
    s.zoom_camera_position,
    s.zoom_camera_target,
    s.camera_fov,
    s.pan_enable,
    s.instant_move,
    COALESCE(s.sky, t.default_sky) AS sky,
    s.free_explore,
    s.explore_area,
    sc.bbox_min,
    sc.bbox_max,
    sc.transform_7dof,
    ( SELECT ma.file_url
           FROM public.model_asset ma
          WHERE ((ma.scene_id = s.scene_id) AND (NOT ma.is_proxy))
          ORDER BY ma.lod_level
         LIMIT 1) AS model_url,
    n.audio_url AS narration_url,
    n.captions_vtt_url,
    n.duration_ms AS narration_duration_ms,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', h.id, 'entity_id', h.entity_id, 'popup_title', h.popup_title, 'popup_text', h.popup_text, 'media_url', h.media_url, 'media_type', h.media_type, 'media_caption', h.media_caption, 'orb_position', h.orb_position, 'camera_position', h.camera_position, 'camera_target', h.camera_target) ORDER BY h.order_index) AS jsonb_agg
           FROM public.highlight h
          WHERE (h.story_id = s.id)), '[]'::jsonb) AS highlights
   FROM (((public.tour t
     JOIN public.story s ON ((s.tour_id = t.id)))
     LEFT JOIN public.scene sc ON ((sc.id = s.scene_id)))
     LEFT JOIN public.narration n ON ((n.story_id = s.id)));


ALTER VIEW public.v_tour_stop OWNER TO duongthanhhung;

