INSERT INTO public.entity VALUES ('a14f2c97-a5da-5dd0-a0be-bcc1a363d6bf', 'Bảo tàng Cổ vật Cung đình Huế', 'bao tang co vat cung dinh hue', 'place', 'Bảo tàng Cổ vật Cung đình Huế là một viện bảo tàng trực thuộc sự quản lý của Trung tâm bảo tồn di tích cố đô Huế. Tòa nhà chính của viện bảo tàng bằng gỗ, có 128 cây cột gỗ quý, trên các cột có hình chạm khắc tứ linh: long - li - quy - phụng và hơn 1000 bài thơ bằng chữ Hán. Tòa nhà này chính là điện Long An xây năm 1845 dưới thời vua Hiến tổ nhà Nguyễn, niên hiệu là Thiệu Trị. Hiện bảo tàng trưng bày hơn 300 hiện vật bằng vàng, sành, sứ, pháp lam Huế, ngự y và ngự dụng, trang phục của hoàng thấ', NULL, '383b7888-a08a-56cd-a302-458219325ca7', '1b9fd526-15c3-587f-bd11-0935a9052f4c', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('90e279c3-87c5-5fa4-b104-d1355abfe734', 'Ca Huế', 'ca hue', 'artifact', 'Ca Huế là loại hình âm nhạc truyền thống được phát triển từ rất lâu đời, được cho là từ thời chúa Nguyễn trên mảnh đất Thuận Hóa xưa, tức Huế ngày nay. Ca Huế là loại hình đàn hát ở thính phòng mang phong cách tự sự, ngâm ngợi, tri âm tri kỷ, với số lượng năm bảy người đàn ca với nhau. Các làn điệu và bài bản đạt đến trình độ hoàn chỉnh cả về phần nhạc và lời, với nội dung giàu chất thơ và trữ tình. Lời ca thể hiện tình cảm đối với non sông, đất nước, đồng loại cùng những tâm sự, nỗi niềm riêng.', NULL, 'ef670cf1-72bf-50be-8b48-61cd08545045', '56ba87b2-8b58-5211-965e-6b22da303065', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('5da3c05e-57ac-5263-9d7d-cd0bd664422d', 'Cao lầu', 'cao lau', 'artifact', 'Cao lầu là một món mì ở Đà Nẵng, Việt Nam. Đây được xem là món ăn đặc sản của Hội An. Món mì này có sợi mì màu vàng, được dùng với tôm, thịt xíu (xá xíu), các loại rau sống và rất ít nước dùng. Sợi mì màu vàng là do bột được hòa chung với tro từ một loại cây ở địa phương. Theo lịch sử ghi chép, cao lầu đã xuất hiện từ thế kỷ 17. Trong khoảng thời gian này, các thương nhân Trung Quốc và Nhật Bản thường xuyên lui tới cảng Hội An. Họ đã mang theo văn hóa ẩm thực riêng của nước họ, rồi dần dần tạo đ', NULL, 'b01d32cf-08c3-5a97-be57-7e6e080c8676', '616c91ca-af86-5e8a-a12d-e1cec9cd5c4c', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('a5c08bc1-6dab-5bba-8040-9aebb853220f', 'Chợ Đông Ba', 'cho dong ba', 'place', 'Chợ Đông Ba là một ngôi chợ tại thành phố Huế, Việt Nam. Đây là ngôi chợ truyền thống lâu đời, có lịch sử hơn 100 năm xây dựng và phát triển, được xem là một trong những biểu tượng của vùng đất cố đô Huế. Chợ Đông Ba nằm bên bờ bắc sông Hương, trên đường Trần Hưng Đạo thuộc phường Đông Ba, quận Phú Xuân, thành phố Huế. Mặt bằng chợ nằm trải dài từ chân cầu Trường Tiền đến cầu Gia Hội với tổng diện tích là 47.614 m², bao gồm cả bến, bãi đỗ xe và khu hoa viên đường Chương Dương.', NULL, '92226c35-5026-564e-bd7a-a5b4b3a925a6', 'dc36fbb6-de60-5127-968f-8042fa7e4724', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('67604e75-c2ad-58f1-9550-2159cfb1105f', 'Cung An Định', 'cung an dinh', 'place', 'Cung An Định (安定宮) tọa lạc bên bờ sông An Cựu, xưa thuộc phường Đệ Bát, thị xã Huế (nay tại số 179 đường Phan Đình Phùng, phường Thuận Hóa, thành phố Huế) là cung điện riêng của vua Khải Định từ khi còn là thái tử đến khi làm vua, sau này được Bảo Đại thừa kế và từng sống ở đây sau khi thoái vị.', NULL, '9fb8d0e1-b440-53ca-82de-78865213f951', '4dc775d8-2ab2-54a5-8e31-c3ddfa7d5ef2', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('5b456ce0-202f-51e2-8959-db379f574cd1', 'Cơm hến', 'com hen', 'artifact', 'Cơm hến là một đặc sản ẩm thực Huế. Cơm hến được trình bày dưới hình thức là cơm nguội trộn với hến xào qua dầu và gia vị, nước hến, mắm ruốc, môn bạc hà, bẹ chuối, rau má, rau thơm, giá đỗ, tóp mỡ hoặc bóng bì chiên giòn, sợi mì chiên giòn, ớt màu, đậu phộng nguyên hạt, ớt chưng, tiêu, bột ngọt và muối. Các món cải biên như bún hến và mì hến không phải là đặc sản Huế. Hến ngâm nước gạo một thời gian để thải hết bùn đất, rửa sạch, đem luộc cho đến khi hến mở vỏ. Lấy nước luộc sau khi đã để lắng,', NULL, 'eefa9712-c71d-5982-9e9c-4315fa8e37bd', 'b58da286-6343-5c76-96f0-83264fc68982', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('d49741a4-f0f0-5cee-baf3-ec322e9b07db', 'Cầu Rồng', 'cau rong', 'place', 'Cầu Rồng là cây cầu thứ 6 và là cây cầu mới nhất bắc qua sông Hàn. Vì cây cầu có hình dáng giống một con rồng nên được gọi là Cầu Rồng Cầu Rồng dài 666 m và rộng 37,5 m với 6 làn xe chạy. Cầu được khởi công xây dựng vào ngày 19/7/2009 và chính thức thông xe ngày 29 tháng 3 năm 2013, kinh phí xây cầu gần 1,5 nghìn tỷ đồng (US$88m). Cầu được thiết kế bởi Ammann & Whitney Consulting Engineers với tập đoàn Louis Berger. Việc xây dựng được thực hiện bởi Tổng công ty xây dựng công trình giao thông 1. ', NULL, 'a7f24735-2c1c-5fdd-a267-b3b0f7fb41e9', 'd2ca11e2-b13e-5d91-9d75-780f23293904', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('64c4e498-2779-5363-b474-c51ddf0e070c', 'Cầu Trường Tiền', 'cau truong tien', 'place', 'Cầu Trường Tiền hay cầu Tràng Tiền  là chiếc cầu dài 402,60 m, gồm 6 nhịp dầm thép hình vành lược, khẩu độ mỗi nhịp 67 m. Khổ cầu 6 m, được thiết kế theo kiến trúc Gothic, bắc qua sông Hương, thuộc đoạn Quốc lộ 1 cũ cho đến khi cầu Phú Xuân thay thế vai trò. Đầu cầu phía bắc thuộc phường Phú Xuân; đầu cầu phía nam thuộc phường Thuận Hóa, thành phố Huế, Việt Nam.', NULL, 'c6bc2725-1a55-57f9-9361-3d1687f8c11e', 'dc534bec-3bff-56f8-bb80-8744dbdf74fb', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('97009e8b-6a03-5cc5-bef1-91d62d6f729f', 'Festival Huế', 'festival hue', 'event', 'Festival Huế được tổ chức 2 năm một lần, là một sự kiện văn hóa lớn được tổ chức tại Huế vào các năm chẵn nhằm mục đích tưởng nhớ về những giá trị truyền thống tại cố đô Huế. Tham gia lễ hội này, du khách sẽ được thưởng thức những màn biểu diễn nghệ thuật đường phố, ngâm thơ, các buổi trưng bày đầy màu sắc, hòa nhạc, chơi trống và xem các bộ phim lịch sử. Festival Huế đầu tiên có tên là Festival Việt-Pháp được tổ chức năm 1992. Cho đến năm 2000 thì đổi tên là Festival Huế.', NULL, 'e3d55603-863a-5fd9-8f2f-b5784b241f1f', '98868fc8-8c64-54b3-9fe3-497b35bf84b5', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('49519007-4498-557d-a0ae-789a970cbac8', 'Hoàng thành Huế', 'hoang thanh hue', 'place', 'Hoàng thành Huế (chữ Hán: 皇城) hay còn được gọi là Đại Nội (大內), là vòng thành thứ hai bên trong Kinh thành Huế, có chức năng bảo vệ các cung điện quan trọng nhất của triều đình, các miếu thờ tổ tiên nhà Nguyễn và bảo vệ Tử Cấm thành - nơi dành riêng cho vua và hoàng gia. Hoàng thành và Tử Cấm thành thường được gọi chung là Đại Nội có diện tích khoảng 520ha.', NULL, 'f7045f02-de2a-55d7-bab6-672b3723d6f0', '5c281a12-3b48-5a7a-829d-67f9a9372b5a', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('7a4672f2-18bc-5e11-a78c-7983fe1ad412', 'Hát tuồng', 'hat tuong', 'artifact', 'Tuồng (Chữ Nôm: 從), hát bộ, hát bội (Chữ Nôm: 喝佩) là những cách gọi một loại hình nhạc kịch thịnh hành tại Việt Nam. Khác với các loại hình nhạc kịch khác như chèo, cải lương,… tuồng mang theo âm hưởng hùng tráng với những tấm gương nhân vật tận trung báo quốc, xả thân vì đại nghĩa, những bài học về lẽ ứng xử của con người giữa cái chung và cái riêng, giữa gia đình và Tổ quốc, chất bi hùng là một đặc trưng thẩm mỹ của nghệ thuật Tuồng. Có thể nói Tuồng là sân khấu của những người anh hùng,... Lo', NULL, '482da899-c20e-563f-aa19-bef512c33f69', '751f97ab-eda4-5bcf-989e-5f4b625fe1c6', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('838ca2e4-e77e-59a6-917f-15d7f66511ee', 'Hổ Quyền', 'ho quyen', 'place', 'Hổ Quyền (chữ Hán 虎圈) là một di tích trong quần thể di tích cố đô Huế, tọa lạc tại địa phận tổ dân phố Trường Đá, phường Thủy Biều, quận Thuận Hóa, thành phố Huế, nơi đây là một chuồng nuôi hổ và là một đấu trường độc đáo mà có thể không hề có ở bất cứ nơi đâu trên thế giới. Dưới triều Nguyễn đây là đấu trường của những cuộc tử chiến giữa voi và hổ nhằm tế thần trong ngày hội và phục vụ nhu cầu giải trí tiêu khiển cho vua, quan lại và người dân.', NULL, '170a81c2-c8ff-5b95-be36-45baefde6642', '9544a2da-5c99-5b49-a4fa-98ee51ff7b05', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('4f268c61-71ec-5be3-b8d9-a3c221d6094b', 'Kinh thành Huế', 'kinh thanh hue', 'place', 'Kinh thành Huế, Đại nội Huế, Hoàng thành Huế hay Cố đô Huế là một tòa thành ở cố đô Huế, nơi đóng đô của triều đại nhà Nguyễn trong suốt 143 năm từ 1802 đến khi thoái vị vào năm 1945. Hiện nay, Kinh thành Huế là một trong số các di tích thuộc cụm Quần thể di tích Cố đô Huế được UNESCO công nhận là Di sản Văn hoá Thế giới. Kinh thành Huế được vua Gia Long tiến hành khảo sát từ năm 1803, khởi công xây dựng từ 1805 và hoàn chỉnh vào năm 1832 dưới triều vua Minh Mạng. Hiện nay, Kinh thành Huế thuộc ', NULL, '581f2d53-816f-5d38-8aa7-a99f0521b3ad', '326b4ca6-d468-5c4a-b8f6-17de30a0ccfc', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('97a0563c-3939-5208-9346-97bb899d0735', 'Làng Non Nước', 'lang non nuoc', 'place', 'Làng đá mỹ nghệ Non Nước là một làng nghề điêu khắc đá tại phường Hòa Hải, quận Ngũ Hành Sơn, thành phố Đà Nẵng, gắn với khu vực Ngũ Hành Sơn. Nghề điêu khắc đá mỹ nghệ Non Nước được ghi danh là di sản văn hóa phi vật thể cấp quốc gia năm 2014. Tư liệu di sản ghi nhận nghề được hình thành khoảng thế kỷ 17, khởi dựng bởi một nhóm thợ di cư, ban đầu tập trung sản phẩm dân dụng; sang đầu thế kỷ 19 nghề phát triển cùng nhu cầu xây dựng của triều Nguyễn với các hạng mục cung điện và lăng tẩm. Bộ công', NULL, 'a5f67983-d814-521e-8f23-9b8408d3149f', '63728299-c506-50e0-9615-5078a136e812', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('b7589bfc-5283-50b9-82fe-da7d13fff2ef', 'Mè xửng', 'me xung', 'artifact', 'Kẹo mè xửng hay mè xửng là một đặc sản có nguồn gốc từ thành phố Huế, Việt Nam. Kẹo được làm từ bột năng, mạch nha pha trộn lẫn với đậu phộng, có mè bao phủ xung quanh kẹo, được cắt từng miếng vuông nhỏ (bao giấy bóng nhỏ) gói trong hộp.', NULL, 'c774aec2-5681-5f69-9644-c2b235de49c6', 'd995e6b8-a143-5c05-a591-02266718247d', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('fa3bfd1c-49d8-5862-b34a-c528f21b9cc5', 'Mì Quảng', 'mi quang', 'artifact', 'Mì Quảng (tức là Mì của xứ Quảng) là một món ăn có nguồn gốc xuất xứ và cũng là đặc sản của Quảng Nam (nay thuộc thành phố Đà Nẵng), Việt Nam. Mì Quảng là một loại sợi mì, thường được làm từ bột gạo xay mịn với nước từ hạt dành dành và trứng cho có màu vàng và tráng thành từng lớp bánh mỏng, sau đó thái theo chiều ngang để có những sợi mì mỏng khoảng 5 -10mm. Khi thực hiện món ăn, dưới lớp mì là các loại rau sống, mì Quảng phải ăn kèm với rau sống 9 vị thì mới tạo nên được hương vị nồng nàn: hún', NULL, '50dd085a-8796-55a8-98fa-be2cc5322aa7', 'ae252e93-4417-519e-b943-c5c9f0e6dda0', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('62086806-8b6c-5393-8fff-33e5528047d8', 'Sông Hương', 'song huong', 'place', 'Sông Hương (hay Hương Giang, Hán Nôm: 香江, Chữ Nôm: 瀧香) là con sông nổi tiếng chảy qua trung tâm thành phố Huế, tỉnh Thừa Thiên Huế, miền Trung Việt Nam. Sông Hương không chỉ là biểu tượng văn hóa, lịch sử và du lịch của xứ Huế mà còn là nguồn cảm hứng thơ ca, âm nhạc nghệ thuật cho nhiều thế hệ nghệ sĩ.', NULL, '4abb1fb1-e0cb-5883-acf6-fd56a70b6c69', '176e7c55-9aa6-5e79-848d-e125ab3112ab', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('b1e3c00f-8485-5b21-a6a3-fb04425aa358', 'Lăng Dục Đức', 'lang duc duc', 'place', 'Lăng Dục Đức tên chữ An Lăng (安陵) là một di tích trong quần thể di tích cố đô Huế, là nơi an táng vua Dục Đức, vị vua thứ năm của triều đại nhà Nguyễn. Lăng tọa lạc tại thôn Tây Nhất, làng An Cựu, xưa thuộc huyện Hương Thủy, nay thuộc phường An Cựu, quận Thuận Hóa, thành phố Huế, cách trung tâm thành phố chưa đầy 2 km. Quần thể lăng Dục Đức là khái niệm ngày nay để chỉ quần thể kiến trúc rộng rộng gần 6ha, bao gồm lăng Dục Đức (tức An Lăng), lăng Thành Thái, lăng Duy Tân cùng tẩm mộ của các hoàn', NULL, '7bfaa91f-3559-5d21-8393-bc5ff224f812', '87f11876-dffc-564f-bebd-5e4e09125941', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('2f085816-a9df-5d8d-9c96-f6fa46394a27', 'Lăng Gia Long', 'lang gia long', 'place', 'Lăng Gia Long  hay Thiên Thọ Lăng (天授陵), là lăng tẩm của hoàng đế Gia Long (1762–1820), vị vua sáng lập triều Nguyễn. Lăng Gia Long thực ra là một quần thể nhiều lăng tẩm trong hoàng quyến, nay thuộc địa phận phường Kim Long, thành phố Huế.', NULL, 'f9310ca3-c5db-51fa-b1ed-034d691aa4b4', 'e9a50938-b989-517c-966f-d0abfe18c797', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('6624ed1a-baab-5129-bd8d-ac08a987a30f', 'Lăng Khải Định', 'lang khai dinh', 'place', 'Lăng Khải Định, còn gọi là Ứng Lăng (應陵) là lăng tẩm của Hoàng đế Khải Định (1885-1925), vị Hoàng đế thứ 12 Triều Nguyễn. Lăng tọa lạc tại núi Châu Chữ, phường Thủy Xuân, thành phố Huế. Công trình kiến trúc này nằm trong quần thể di tích cố đô Huế, di sản thế giới đã được UNESCO công nhận từ năm 1993.', NULL, '4e8b2eb5-e4c7-57b4-848b-832b542da66d', '9a48e35a-638c-5729-b9e9-70f3129fbb62', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('de79dc51-f9ed-5322-b674-10606893d937', 'Lăng Minh Mạng', 'lang minh mang', 'place', 'Lăng Minh Mạng (hay còn gọi là Minh Mệnh) có tên chữ là Hiếu lăng (孝陵), do hoàng đế Thiệu Trị thời nhà Nguyễn cho xây dựng, nằm trên núi Cẩm Kê, ấp An Bằng, phường Long Hồ, quận Phú Xuân, thành phố Huế, gần ngã ba Bằng Lãng là nơi hội lưu của hai dòng Hữu Trạch và Tả Trạch hợp thành sông Hương, cách trung tâm thành phố Huế 12 km. Lăng Minh Mạng được xây dựng từ năm 1840 đến năm 1843 thì hoàn thành, huy động tới mười nghìn thợ và lính.', NULL, '1ff1fe7e-e548-5509-8868-ce7849aa56c8', 'c479c0d3-3274-5d8c-a2c7-ae5075206aab', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('f716d46a-8d44-5149-b1f5-9389de7c3ad4', 'Lăng Thiệu Trị', 'lang thieu tri', 'place', 'Lăng Thiệu Trị có tên chữ là Xương Lăng (昌陵) là nơi chôn cất hoàng đế Thiệu Trị. Đây là một di tích trong Quần thể di tích cố đô Huế được UNESCO công nhận là di sản văn hóa thế giới ngày 11 tháng 12 năm 1993.', NULL, '6d2c111d-d401-573e-9843-e69bff105c1a', '909ef30d-4cbb-5657-9878-b1edb7b98cd8', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('f83284d9-4cde-5aaa-96ea-60f63ffb128d', 'Lăng Tự Đức', 'lang tu duc', 'place', 'Lăng Tự Đức (chữ Hán: 嗣德陵) là một quần thể Di tích công trình kiến trúc, trong đó có nơi chôn cất Tự Đức, tọa lạc trong một thung lũng hẹp thuộc làng Dương Xuân Thượng, tổng Cư Chánh, nay là tổ dân phố Thượng Ba, phường Thủy Xuân, thành phố Huế. Lúc mới xây dựng, Tự Đức đặt tên là Khiêm Cung (謙宮). Sau khi Tự Đức băng hà, lăng được đổi tên thành Khiêm Lăng (謙陵). Lăng Tự Đức có kiến trúc cầu kỳ, phong cảnh sơn thủy, hữu tình và là một trong những lăng tẩm đẹp nhất của hoàng gia nhà Nguyễn. Tự Đức ', NULL, 'a0503629-579a-5a8f-a14a-c4281ae98846', 'fb7e27d9-952c-58f2-aae3-039c5a917798', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('c6958c4c-515a-5f44-8be0-89dd1a9c80e6', 'Bảo tàng Điêu khắc Chăm Đà Nẵng', 'bao tang dieu khac cham da nang', 'place', 'Bảo tàng Điêu khắc Chăm Đà Nẵng, còn được gọi là Bảo tàng Chàm (dịch từ Musée Cham) là bảo tàng sưu tầm, lưu giữ và trưng bày hiện vật Chăm quy mô nhất ở Việt Nam. Bảo tàng được xây dựng và khánh thành bởi Trường Viễn Đông Bác cổ (École Française d''Extrême-Orient, EFEO), chuyên sưu tập, cất giữ và trưng bày các di vật điêu khắc của vương quốc Chăm Pa tìm thấy ở các tháp, thành lũy Chăm tại các tỉnh duyên hải Nam Trung Bộ từ Quảng Bình, Quảng Trị tới Bình Thuận và các tỉnh Tây Nguyên.', NULL, 'c86914e1-f68b-5761-a721-49bcb747bd9e', 'a0312234-27b5-58e7-8e3c-4a8a2b983e66', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('6c256ae2-5fdd-50a0-b7b9-166c860bfcd0', 'Ngũ Hành Sơn', 'ngu hanh son', 'place', 'Ngũ Hành Sơn (chữ Hán: 五行山) là một danh thắng gồm 6 ngọn núi đá vôi nhô lên trên một bãi cát ven biển, trên một diện tích khoảng 2 km² nằm cách trung tâm thành phố Đà Nẵng, Việt Nam khoảng 8 km về phía Đông Nam, ngay trên tuyến đường Đà Nẵng - Hội An; nay thuộc phường Ngũ Hành Sơn, thành phố Đà Nẵng. Ngũ Hành Sơn gồm các ngọn núi: Mộc Sơn, Thủy Sơn (lớn, cao và đẹp nhất), Thổ Sơn, Kim Sơn và Hỏa Sơn (có hai ngọn là Dương Hỏa Sơn và Âm Hỏa Sơn). Ngày 22 tháng 3 năm 1990, khu danh thắng này đã đượ', NULL, 'f86652b3-08a1-51f7-a871-8d34f2f84484', 'f9d31889-e63f-561a-951b-abe318a67fe8', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('9af558f7-f735-5381-9b00-8c3505e830e8', 'Nhà thờ chính tòa Đà Nẵng', 'nha tho chinh toa da nang', 'place', 'Nhà thờ chính tòa Đà Nẵng, tiếng Anh: Da Nang Cathedral, tiếng Pháp: Cathédrale de Đà Nẵng), thường được gọi tắt là Nhà thờ con gà Đà Nẵng, Nhà Thờ Lớn Đà Nẵng, hoặc Nhà Thờ Tourane, là nhà thờ chính tòa củagiáo phận Đà Nẵng toạ lạc tại số 156 Trần Phú, P. Hải Châu, Thành Phố Đà Nẵng, Việt Nam. Nhà thờ không chỉ là biểu tượng của Công giáo ở Đà Nẵng, mà còn là một trong những công trình kiến trúc độc đáo của Thành phố Đà Nẵng và điểm đến nổi tiếng với du khách. Tên gọi ban đầu của nhà thờ là Nhà', NULL, '09c1f2a1-9ecf-5641-9399-9d43d782be10', '0669d945-ab58-5fdc-89be-f51d215980f6', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('1e4a828a-a0cd-5262-825a-77c7bb57b6bd', 'Nhã nhạc cung đình Huế', 'nha nhac cung dinh hue', 'artifact', 'Nhã nhạc cung đình Huế là thể loại nhạc của cung đình thời phong kiến, được biểu diễn vào các dịp lễ hội (vua đăng quang, băng hà, các lễ hội tôn nghiêm khác) trong năm của các triều đại nhà Nguyễn của Việt Nam. Nhã nhạc cung đình Huế đã được UNESCO công nhận là Kiệt tác truyền khẩu và phi vật thể nhân loại vào năm 2003. Theo đánh giá của UNESCO, "trong các thể loại nhạc cổ truyền ở Việt Nam, chỉ có Nhã nhạc đạt tới tầm vóc quốc gia".  "Nhã nhạc đã được phát triển từ thế kỷ 13 ở Việt Nam đến thờ', NULL, 'cfeaaffc-980c-5565-a3ce-2fbd4911c714', '1febdd01-1ee0-5245-b65f-409368b0c436', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('9a984109-4304-59bc-a425-a708755be8b3', 'Sông Hàn', 'song han', 'place', 'Sông Hàn (chữ Nôm: 滝瀚), còn gọi là Hàn giang (chữ Hán: 瀚江. Chữ Hàn này khác với ''Hàn'' Quốc, mà là ''Hàn'' trong ''Hàn'' Lâm và thêm bộ thủy, thực ra phải đọc là "Hãn"), là một con sông nằm ở Đà Nẵng. Nó bắt nguồn từ tỉnh Quảng Nam và đổ ra Biển Đông tại vịnh Đà Nẵng.', NULL, '096b6c05-4fcf-5e60-b676-c89b11e10264', 'a5f5c15b-7bc7-5133-b521-94913433a5d3', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('d7f0c586-a3dd-512a-9662-b5a663329464', 'Bài chòi', 'bai choi', 'artifact', 'Bài chòi là một loại hình nghệ thuật dân ca và trò chơi dân gian đặc trưng ở miền Trung Việt Nam, về sau đã được phát triển thành một loại hình sân khấu ca kịch. Lúc 17h15’ (giờ Hàn Quốc) ngày 7 tháng 12 năm 2017 (khoảng 15h15’ giờ Việt Nam), tại Phiên họp Ủy ban Liên Chính phủ Công ước 2003 về bảo vệ di sản văn hóa phi vật thể lần thứ 12 của UNESCO diễn ra tại Jeju, hồ sơ Nghệ thuật Bài chòi Trung Bộ của Việt Nam đã được ghi danh là di sản văn hóa phi vật thể đại diện của nhân loại.', NULL, 'b12e9726-c3e9-53ea-beb7-499c966481f9', 'c248bb82-1274-5ba6-afa3-f47e001394fa', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('74ebb60d-07fe-580a-8fed-5e7e7a5cbc31', 'Bán đảo Sơn Trà', 'ban dao son tra', 'place', 'Núi Sơn Trà, hoặc gọi là núi Khỉ, là một ngọn núi và bán đảo thuộc phường Sơn Trà, thành phố Đà Nẵng, Việt Nam, phía tây giáp vịnh Đà Nẵng, phía đông bắc và phía đông nam giáp biển Đông, phía tây nam do phù sa sông Hàn bồi đắp mà nối với đất liền hình thành bán đảo Sơn Trà, là điểm cuối cùng của dãy núi Trường Sơn Bắc. Bến cảng Tiên Sa thuộc cảng Đà Nẵng nằm ở chân núi phía tây, sát gần bãi biển Tiên Sa. Địa điểm này là khu bảo tồn thiên nhiên nổi tiếng và thắng cảnh du lịch nằm gần thành phố. Đ', NULL, '29686e73-690a-5ac7-a5c5-9552d98beba7', 'f3fe78e8-0d25-502b-a673-6b2f1cf7ff59', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('7bebefa4-0bf2-5b8d-a3e2-f5e6127f7c9d', 'Bún bò Huế', 'bun bo hue', 'artifact', 'Bún bò Huế là một trong những đặc sản của thành phố Huế, mặc dù món bún này phổ biến trên cả ba miền ở Việt Nam và cả người Việt tại hải ngoại. Tại Huế, món này được gọi đơn giản là "bún bò" hoặc gọi cụ thể hơn là "bún bò - giò heo". Các địa phương khác gọi là "bún bò Huế", "bún bò gốc Huế" để chỉ xuất xứ của món ăn này. Bún bò chính gốc Huế có nguyên liệu chính là bún, thịt bắp bò, giò heo, cùng nước dùng có màu đỏ đặc trưng do ớt và vị sả và ruốc. Trong nước dùng của bún, người Huế thường nêm ', NULL, '9c6f92f5-ec62-5b63-8bae-632c6038a4a2', 'e7767ba4-c51c-5eba-b5ee-9106736961db', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('d8b945f7-ac76-5c3b-a487-0c8872396eec', 'Bún chả cá', 'bun cha ca', 'artifact', 'Bún chả cá là một món ăn đặc trưng của khu vực MIền Trung Việt Nam. Cá sau khi được chế biến thành chả, cùng với bún và các nguyên phụ liệu khác là những thành phần của một tô bún chả cá. Lý do chính để bún chả cá phổ biến tại Trung Bộ hơn là các miền khác là do hầu như miền này có đủ các loại cá ngon dùng để chế biến thành chả cá như là: cá thu, cá thác lác, cá mối, cá chuồn, cá nhồng. Bún chả cá thường được tìm thấy tại các tỉnh nằm ven biển, vì các vùng này là nơi có sản lượng đánh bắt cá cao', NULL, '3c8f5e33-5368-5304-bc1f-f90863f7f144', '56878c19-21b6-5da8-bb6d-5f4815904496', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('bafb2ab7-8b86-54a2-8a84-90b8ae78c194', 'Chùa Linh Ứng', 'chua linh ung', 'place', 'Chùa Linh Ứng (chữ Hán: 靈應寺) – Bãi Bụt, Sơn Trà, Đà Nẵng là một trong ba ngôi chùa cùng mang tên Linh Ứng ở Đà Nẵng. Do cố ý vì mục đích kinh doanh hay vì một lý do nào đó mà 2 ngôi chùa mới xây sau này đều cùng tên với ngôi chùa cổ.Không rõ là do vô tình hay do chữ duyên mà cả ba ngôi chùa đều được tọa lạc trên những vị thế đắc địa của thành phố Đà Nẵng, tạo thành một "tam giác" linh thiêng trong thành phố. Đó là chùa Linh Ứng Non Nước, nằm trên hòn Thủy sơn của một trong 5 ngọn núi Ngũ Hành Sơ', NULL, '71b91170-4e53-5244-9a45-0b84f13419ea', 'dc922d9c-b047-5b1f-a27d-7fc120732543', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('9eb961e9-9fbf-5d4c-8d4a-cab03cdeb720', 'Chùa Thiên Mụ', 'chua thien mu', 'place', 'Chùa Thiên Mụ hay còn gọi là chùa Linh Mụ là một ngôi chùa cổ nằm trên đồi Hà Khê, tả ngạn sông Hương, cách trung tâm thành phố Huế (Việt Nam) khoảng 5 km về phía tây. Chùa Thiên Mụ chính thức khởi lập năm Tân Sửu (1601), đời chúa Tiên Nguyễn Hoàng - vị chúa Nguyễn đầu tiên ở Đàng Trong.', NULL, '666e1ca0-bc29-5eac-8fce-4a3cbee913fc', 'ffa0e230-b8e5-50dd-b536-39e99840de23', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('f47f3699-e3b5-52c6-ba3f-d0450704e356', 'Chùa Từ Hiếu', 'chua tu hieu', 'place', 'Chùa Từ Hiếu hay Tổ đình Từ Hiếu (Chữ Hán: 慈孝寺, Từ Hiếu Tự) là tên một ngôi chùa ở thôn Dương Xuân Thượng III, phường Thủy Xuân, thành phố Huế. Chùa là một trong những ngôi cổ tự lớn và là một danh lam có tính văn hóa và lịch sử của cố đô Huế.', NULL, '7d72b2f8-b5c9-5f15-aff2-1b172112b871', '24b09eb0-68ff-59b5-b831-26b2b0c090ac', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('c58f18c5-4ce6-5c0d-8ac8-c8d5678b9b9e', 'Lăng Đồng Khánh', 'lang dong khanh', 'place', 'Lăng Đồng Khánh hay Tư Lăng (思陵) là một di tích trong quần thể di tích cố đô Huế đây là nơi an táng hoàng đế Đồng Khánh, lăng tọa lạc giữa một vùng quê thuộc làng Cư Sĩ, xã Dương Xuân trước đây, nay là thôn Thượng Hai, phường Thủy Xuân, thành phố Huế. Đồng Khánh tên húy là Nguyễn Phúc Ưng Đường, con trai cả của Kiên Thái Vương Nguyễn Phúc Hồng Cai (1845-1876), người sinh thành 3 vị vua: Kiến Phúc (1883-1884), Hàm Nghi (1884-1885) và Đồng Khánh (1886-1889). Ca dao Huế từng nói về vương nghiệp của', NULL, 'd32f0626-7be4-5adb-bd08-9f47cafe82b0', '9f98119e-fc2f-50a1-8a36-6108b370b637', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('de110c13-8b44-5949-aa1f-02b392661028', 'Lễ Cầu ngư', 'le cau ngu', 'event', 'Lễ Cầu ngư là một dạng lễ hội dân gian gắn với cộng đồng ngư dân ven biển, tập trung vào các nghi lễ cầu an, cầu mùa và cầu cho chuyến đánh bắt thủy sản thuận lợi. Thực hành phổ biến ở Việt Nam gắn với tín ngưỡng thờ cá Ông (thờ cá voi) và không gian thờ tự của làng chài như lăng thờ, vạn chài hoặc miếu thờ. Ở bình diện so sánh, nhiều cộng đồng ven biển cũng duy trì nghi thức cầu an và lễ hội biển dưới các hình thức khác nhau, như tín ngưỡng Mazu (媽祖), Yeongdeunggut (영등굿) trên Jeju, Sedekah Laut', NULL, '26d8f005-05a6-5359-b772-ad3c7541e7dc', 'e1e9bdb8-8b4d-5fec-b70e-fb27106b1a7e', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('e7cb7950-b047-5644-9bb8-9edf49a08673', 'Bánh bèo', 'banh beo', 'artifact', 'Bánh bèo là một món bánh xuất thân từ Cố Đô Huế rất thịnh hành ở miền Trung, ngoài ra cũng phổ biến ở miền Nam Việt Nam. Bánh bèo đã trở thành một nét đẹp trong văn hóa ẩm thực của người dân Việt Nam từ bao đời nay. Tên bánh bèo có thể xuất phát từ hình dạng của nó: giống như cái lá của cây bèo. Bánh bèo là sự kết hợp của 3 yếu tố chính đó là bánh làm từ bột gạo, nhân để rắc lên bánh làm bằng tôm xay nhuyễn, và nước chấm. Nước chấm bánh bèo là một hỗn hợp với thành phần chính là nước mắm và thườ', NULL, '9b392de6-cd5d-5307-84f7-88e14e19a1d0', 'ebc13e61-118e-5f90-9e59-129d915e87f7', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('4bf11d16-1100-5a50-b78e-e5b82ed71e92', 'Bánh bột lọc', 'banh bot loc', 'artifact', 'Bánh bột lọc là một món ăn truyền thống của Việt Nam, có nguồn gốc từ Huế. Món bánh này phổ biến ở Hà Nội, Ninh Bình, các tỉnh miền Trung như Nghệ An, Đà Nẵng, và đặc biệt là Huế. Đây không chỉ là một món ăn vặt mà còn mang đậm giá trị văn hóa và lịch sử của người Việt. Bánh bột lọc xuất phát từ Huế, kinh đô của triều đại Nguyễn, và gắn liền với ẩm thực cung đình. Món ăn này được cho là đã tồn tại hàng trăm năm, ban đầu phục vụ vua chúa và tầng lớp quý tộc, thể hiện sự tinh tế và khéo léo trong ', NULL, 'e55342ae-f7ac-5e4b-ab70-dfe24886baf4', 'd5990666-39f6-5d9b-abe2-c9a6185169b1', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('772f5415-ac69-527c-8f3c-12c92c7a5f4c', 'Bánh khoái', 'banh khoai', 'artifact', 'Bánh xèo là một loại bánh phổ biến ở châu Á, phiên bản bánh xèo của Nhật Bản và Triều Tiên có bột bên ngoài, bên trong có nhân là tôm, thịt, giá đỗ, kim chi, khoai tây, hẹ, (bánh xèo Triều Tiên); tôm, thịt, cải thảo (Nhật Bản) được rán màu vàng, đúc thành hình tròn hoặc gấp lại thành hình bán nguyệt. Tuỳ theo từng địa phương tại Việt Nam mà bánh được thưởng thức với nét đặc trưng riêng. Thường có 2 phương pháp chính: đổ bánh xèo giòn và bánh xèo dai. Ăn bằng hai cách: ăn bốc hoặc ăn bằng đũa.', NULL, '424c556a-99e9-53d1-b6de-ef44bacd2a52', '45589702-9288-55a5-a95b-83f0c2d3adb1', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('2b842640-ec4f-56c1-9d4d-aaee67ec524c', 'Chùa Từ Đàm', 'chua tu dam', 'place', 'Chùa do Thiền sư Minh Hoằng - Tử Dung khai sơn vào khoảng cuối thế kỉ XVII, và sau đó được đặt tên là chùa Ấn Tôn (印宗寺, hay Tông), với ý nghĩa là "lấy sự truyền tâm làm tông chỉ". Năm 1702, nhà sư Liễu Quán (về sau cũng là một cao tăng) đến chùa, xin tham học với Thiền sư Minh Hoằng - Tử Dung Năm 1703, Thiền sư Minh Hoằng - Tử Dung cho trùng tu chùa. Cũng trong năm này, chúa Nguyễn Phúc Chu ban cho chùa tấm biển Sắc Tứ Ấn Tôn Tự. Sau khi Sư viên tịch, theo lời phó chúc, học trò của Sư là Thiền s', NULL, 'e774e9ec-1db8-535b-9824-7bea34d127d6', 'ac63e9fb-435c-56bd-8c21-602cf156c268', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('4e333232-98df-5528-a1c7-17e54e3503be', 'Làng Thanh Hà', 'lang thanh ha', 'place', 'Làng gốm Thanh Hà là một làng nghề gốm nằm ở khối phố Nam Diêu, phường Hội An Tây, thành phố Đà Nẵng. Làng gắn với không gian đô thị - thương cảng Hội An và các tuyến giao thông thủy trên sông Thu Bồn. Từ năm 2019, nghề gốm Thanh Hà được đưa vào Danh mục di sản văn hóa phi vật thể quốc gia thuộc loại hình nghề thủ công truyền thống. Không gian du lịch gắn với làng nghề gồm các hoạt động trải nghiệm làm gốm và Công viên đất nung Thanh Hà (còn gọi là "Terracotta Park"), một công trình đạt giải "Cô', NULL, 'a7c18001-0445-5b67-a1c1-6bce801db479', '103ce9cc-fcac-5d71-a89b-611d29ec0890', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('56854e92-15ff-50b5-b946-ca771555fee0', 'Thành Điện Hải', 'thanh dien hai', 'place', 'Thành Điện Hải là một di tích quốc gia đặc biệt tọa lạc tại thành phố Đà Nẵng, Việt Nam. Tòa thành được xây dựng lần đầu vào năm Gia Long thứ 12 (năm 1813) với mục đích kiểm soát tàu thuyền và trấn giữ Đà Nẵng. Đến năm Minh Mạng thứ 4 (năm 1823), thành được di dời và xây dựng lại theo kiến trúc kiểu Vauban. Đây là thành lũy có vai trò vô cùng quan trọng góp phần đánh bại cuộc tấn công của thực dân Pháp vào Đà Nẵng những năm 1858–1860.', NULL, 'ecb3be4e-8969-56a8-b0b4-a95be5f7f8a5', 'f0a3b0a3-ee36-54d2-bc7c-817d2240fde9', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('f4dca03a-f513-558a-af81-95e86255da9a', 'Điện Hòn Chén', 'dien hon chen', 'place', 'Điện Hòn Chén hay Huệ Nam Điện tọa lạc trên núi Ngọc Trản, phường Long Hồ, quận Phú Xuân, thành phố Huế. Núi Ngọc Trản xưa có tên là Hương Uyển Sơn, sau mới đổi tên là Ngọc Trản (có nghĩa là chén ngọc), dân gian vẫn quen gọi là Hòn Chén vì nó có liên quan đến giai thoại về vua Minh Mạng đánh rơi chén ngọc. Trong quần thể di tích cố đô Huế, có lẽ điện Hòn Chén gắn với nhiều giai thoại nhất. Dân gian còn lưu truyền rằng điện Hòn Chén xưa có tên là Hoàn Chén với ý nghĩa "trả lại chén ngọc", vì vua ', NULL, '16c48654-fe91-5eee-84d1-cf5d33d6286b', '286425ed-37c6-5940-bd6e-18d0f9069b6b', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');
INSERT INTO public.entity VALUES ('a505a426-0955-593b-8048-42e78847bf76', 'Đèo Hải Vân', 'deo hai van', 'place', 'Đèo Hải Vân còn có tên là đèo Ải Vân (vì trên đỉnh đèo xưa kia có 1 cửa ải) hay đèo Mây (vì đỉnh đèo thường có mây che phủ), cao 500 m so với mực nước biển, dài 20 km, cắt ngang dãy dãy núi Bạch Mã (là 1 phần của dãy Trường Sơn chạy cắt ra sát biển) nằm trên quốc lộ 1 ở ranh giới thành phố Huế (ở phía Bắc) và thành phố Đà Nẵng (ở phía Nam), Việt Nam.', NULL, '8cd34a16-c049-51b8-8383-eabc8e421028', 'd758b6a3-78a2-5e70-baba-5cb170921cde', '2026-09-11 17:42:05.026178+00', '2026-09-12 04:55:03.941261+00');


