INSERT INTO public.place_location VALUES ('a9854197-829a-4b67-a5d2-cb261b11338f', '74ebb60d-07fe-580a-8fed-5e7e7a5cbc31', 'phường Sơn Trà', 'Sơn Trà', NULL, 'Đà Nẵng', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/S%C6%A1n_Tr%C3%A0', NULL, 'Núi Sơn Trà, hoặc gọi là núi Khỉ, là một ngọn núi và bán đảo thuộc phường Sơn Trà, thành phố Đà Nẵng, Việt Nam, phía tây giáp vịnh Đà Nẵng, phía đông bắc và phía đông nam giáp biển Đông, phía tây nam do phù sa sông Hàn bồi đắp mà nối với đất liền hình thành bán đảo Sơn Trà, là điểm cuối cùng của dãy núi Trường Sơn Bắc.', 'verified', '2026-09-12 02:21:43.481979', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('185ad121-7737-4c96-8127-009de220b7ca', '6624ed1a-baab-5129-bd8d-ac08a987a30f', 'phường Thủy Xuân', 'Thủy Xuân', NULL, 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Lăng tọa lạc tại núi Châu Chữ, phường Thủy Xuân, thành phố Huế.', 'verified', '2026-09-12 02:21:43.504417', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('31460e8a-3cb8-42e5-8038-9df4a87ea434', 'a14f2c97-a5da-5dd0-a0be-bcc1a363d6bf', 'đường Lê Trực, phường Thuận Thành', 'Thuận Thành', NULL, 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Năm 1958, dưới chế độ Việt Nam Cộng Hoà, nó mang tên là Bảo tàng Huế và hiện này có tên là "Bảo tàng Cổ vật cung đình Huế"
Hiện nay, Bảo tàng cổ vật Cung đình Huế nằm trên đường Lê Trực, phường Thuận Thành, thành phố Huế.', 'verified', '2026-09-12 02:21:43.486299', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('5b779dba-9252-4525-a262-1201f99d76de', 'c6958c4c-515a-5f44-8be0-89dd1a9c80e6', 'phường Hải Châu', 'Hải Châu', NULL, 'Đà Nẵng', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/B%E1%BA%A3o_t%C3%A0ng_%C4%90i%C3%AAu_kh%E1%BA%AFc_Ch%C4%83m_%C4%90%C3%A0_N%E1%BA%B5ng', NULL, 'Địa điểm hoặc bố trí
Tọa lạc trung tâm thành phố Đà Nẵng ở số 2, đường 2 tháng 9, phường Hải Châu, Đà Nẵng, đối diện với Trung tâm truyền hình Việt Nam tại thành phố Đà Nẵng, Bảo tàng Nghệ thuật điêu khắc Chăm Đà Nẵng có tổng diện tích 6.673 m², trong đó phần diện tích trưng bày là 2.000 m².', 'verified', '2026-09-12 02:21:43.489117', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('918ab566-5ba7-4d5a-9ea8-b7ad41545276', 'f47f3699-e3b5-52c6-ba3f-d0450704e356', 'phường Thủy Xuân', 'Thủy Xuân', NULL, 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/Ch%C3%B9a_T%E1%BB%AB_Hi%E1%BA%BFu', NULL, 'Chùa Từ Hiếu hay Tổ đình Từ Hiếu (Chữ Hán: 慈孝寺, Từ Hiếu Tự) là tên một ngôi chùa ở thôn Dương Xuân Thượng III, phường Thủy Xuân, thành phố Huế.', 'verified', '2026-09-12 02:21:43.490747', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('2dfcf287-9605-4c25-bf56-8a152b27ac9d', '2b842640-ec4f-56c1-9d4d-aaee67ec524c', 'số 1 Sư Liễu Quán, phường Thuận Hóa', 'Thuận Hóa', NULL, 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/Ch%C3%B9a_T%E1%BB%AB_%C4%90%C3%A0m', NULL, 'Chùa Từ Đàm là một ngôi chùa cổ danh tiếng ở Huế, chùa hiện tọa lạc tại số 1 đường Sư Liễu Quán, thuộc phường Thuận Hóa, thành phố Huế, Việt Nam.', 'verified', '2026-09-12 02:21:43.492464', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('1731dce7-d0aa-4372-9ca2-ca00a6707c6a', 'a5c08bc1-6dab-5bba-8040-9aebb853220f', 'đường Trần Hưng Đạo thuộc phường Đông Ba, phường Đông Ba', 'Đông Ba', 'Phú Xuân', 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba', NULL, 'Chợ Đông Ba là một ngôi chợ tại thành phố Huế, Việt Nam.', 'verified', '2026-09-12 02:21:43.493921', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('84501486-dba9-4100-bde9-d8e4525a25a6', '64c4e498-2779-5363-b474-c51ddf0e070c', 'phường Phú Xuân', 'Phú Xuân', NULL, 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Đầu cầu phía bắc thuộc phường Phú Xuân; đầu cầu phía nam thuộc phường Thuận Hóa, thành phố Huế, Việt Nam.', 'verified', '2026-09-12 02:21:43.49764', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('0bcd156f-7ec7-4d23-b686-73f7baa329a3', '838ca2e4-e77e-59a6-917f-15d7f66511ee', 'đường Trường Đá, phường Thủy Biều', 'Thủy Biều', 'Thuận Hóa', 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/H%E1%BB%95_Quy%E1%BB%81n', NULL, 'Hổ Quyền (chữ Hán 虎圈) là một di tích trong quần thể di tích cố đô Huế, tọa lạc tại địa phận tổ dân phố Trường Đá, phường Thủy Biều, quận Thuận Hóa, thành phố Huế, nơi đây là một chuồng nuôi hổ và là một đấu trường độc đáo mà có thể không hề có ở bất cứ nơi đâu trên thế giới.', 'verified', '2026-09-12 02:21:43.499177', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('ca481b40-ed14-442a-9f8c-9314eb614726', '97a0563c-3939-5208-9346-97bb899d0735', 'phường Hòa Hải', 'Hòa Hải', 'Ngũ Hành Sơn', 'Đà Nẵng', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/L%C3%A0ng_Non_N%C6%B0%E1%BB%9Bc', NULL, 'Làng đá mỹ nghệ Non Nước là một làng nghề điêu khắc đá tại phường Hòa Hải, quận Ngũ Hành Sơn, thành phố Đà Nẵng, gắn với khu vực Ngũ Hành Sơn.', 'verified', '2026-09-12 02:21:43.5003', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('83ca1150-f398-4a18-8e2b-f17b2b46b911', '4e333232-98df-5528-a1c7-17e54e3503be', 'đường Nam Diêu, phường Hội An Tây', 'Hội An Tây', NULL, 'Đà Nẵng', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/L%C3%A0ng_Thanh_H%C3%A0', NULL, 'Làng gốm Thanh Hà là một làng nghề gốm nằm ở khối phố Nam Diêu, phường Hội An Tây, thành phố Đà Nẵng.', 'verified', '2026-09-12 02:21:43.501412', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('41bce947-01ca-4142-abcc-f8464e61ef5e', 'b1e3c00f-8485-5b21-a6a3-fb04425aa358', 'phường An Cựu', 'An Cựu', 'Hương Thủy', 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/L%C4%83ng_D%E1%BB%A5c_%C4%90%E1%BB%A9c', NULL, 'Lăng tọa lạc tại thôn Tây Nhất, làng An Cựu, xưa thuộc huyện Hương Thủy, nay thuộc phường An Cựu, quận Thuận Hóa, thành phố Huế, cách trung tâm thành phố chưa đầy 2 km.', 'verified', '2026-09-12 02:21:43.502579', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('b0084b36-d450-4a60-881d-eab7741bb20e', '2f085816-a9df-5d8d-9c96-f6fa46394a27', 'phường Kim Long', 'Kim Long', NULL, 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Lăng Gia Long thực ra là một quần thể nhiều lăng tẩm trong hoàng quyến, nay thuộc địa phận phường Kim Long, thành phố Huế.', 'verified', '2026-09-12 02:21:43.50353', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('c7b7fecb-dfc2-49f8-a5ff-b55ab4245709', 'de79dc51-f9ed-5322-b674-10606893d937', 'phường Long Hồ', 'Long Hồ', 'Phú Xuân', 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Lăng Minh Mạng (hay còn gọi là Minh Mệnh) có tên chữ là Hiếu lăng (孝陵), do hoàng đế Thiệu Trị thời nhà Nguyễn cho xây dựng, nằm trên núi Cẩm Kê, ấp An Bằng, phường Long Hồ, quận Phú Xuân, thành phố Huế, gần ngã ba Bằng Lãng là nơi hội lưu của hai dòng Hữu Trạch và Tả Trạch hợp thành sông Hương, cách trung tâm thành phố Huế 12 km.', 'verified', '2026-09-12 02:21:43.505277', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('fa668d6d-aa19-4c58-b215-7ebab15c0156', 'f4dca03a-f513-558a-af81-95e86255da9a', 'phường Long Hồ', 'Long Hồ', 'Phú Xuân', 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Điện Hòn Chén hay Huệ Nam Điện tọa lạc trên núi Ngọc Trản, phường Long Hồ, quận Phú Xuân, thành phố Huế.', 'verified', '2026-09-12 02:21:43.510244', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('2929e991-7787-5977-afe5-ac1b214c5780', '67604e75-c2ad-58f1-9550-2159cfb1105f', '97 đường Phan Đình Phùng', NULL, NULL, 'Thành phố Huế', NULL, NULL, NULL, NULL, 'https://eticket.hueworldheritage.org.vn/diem-den/cung-an-dinh', 'Cung An Định - Trung tâm Bảo tồn Di tích Cố đô Huế', 'An Định là cung điện riêng của vua Khải Định, tọa lạc bên bờ sông An Cựu, xưa thuộc phường Đệ Bát - Thị xã Huế, nay mang số 97 đường Phan Đình Phùng, Thành phố Huế.', 'verified', '2026-09-10 17:00:00', '2026-09-11 17:42:05.026178');
INSERT INTO public.place_location VALUES ('0b1eb17d-e254-46af-a022-d380bddcee45', 'f716d46a-8d44-5149-b1f5-9389de7c3ad4', 'phường Thủy Bằng', 'Thủy Bằng', 'Thuận Hóa', 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/L%C4%83ng_Thi%E1%BB%87u_Tr%E1%BB%8B', NULL, 'Vị trí
Lăng Thiệu Trị nằm dựa lưng vào núi Thuận Đạo, ở địa phận làng Cư Chánh, phường Thủy Bằng, quận Thuận Hóa, thành phố Huế, cách trung tâm thành phố khoảng 8 km.', 'verified', '2026-09-12 02:21:43.506169', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('07ff7e80-db33-4ad0-a1a7-7cbb898b8661', 'f83284d9-4cde-5aaa-96ea-60f63ffb128d', 'đường Thượng Ba, phường Thủy Xuân', 'Thủy Xuân', NULL, 'Huế', NULL, NULL, NULL, NULL, '', NULL, 'Lăng Tự Đức (chữ Hán: 嗣德陵) là một quần thể Di tích công trình kiến trúc, trong đó có nơi chôn cất Tự Đức, tọa lạc trong một thung lũng hẹp thuộc làng Dương Xuân Thượng, tổng Cư Chánh, nay là tổ dân phố Thượng Ba, phường Thủy Xuân, thành phố Huế.', 'verified', '2026-09-12 02:21:43.50727', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('c788b7bc-3f09-4188-84d9-a5edc4016a5b', 'c58f18c5-4ce6-5c0d-8ac8-c8d5678b9b9e', 'phường Thủy Xuân', 'Thủy Xuân', NULL, 'Huế', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/L%C4%83ng_%C4%90%E1%BB%93ng_Kh%C3%A1nh', NULL, 'Lăng Đồng Khánh hay Tư Lăng (思陵) là một di tích trong quần thể di tích cố đô Huế đây là nơi an táng hoàng đế Đồng Khánh, lăng tọa lạc giữa một vùng quê thuộc làng Cư Sĩ, xã Dương Xuân trước đây, nay là thôn Thượng Hai, phường Thủy Xuân, thành phố Huế.', 'verified', '2026-09-12 02:21:43.508478', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('3a8b75c2-bfbb-449d-940a-34ac262955f3', '6c256ae2-5fdd-50a0-b7b9-166c860bfcd0', 'phường Ngũ Hành Sơn', 'Ngũ Hành Sơn', NULL, 'Đà Nẵng', NULL, NULL, NULL, NULL, '', NULL, 'Ngũ Hành Sơn (chữ Hán: 五行山) là một danh thắng gồm 6 ngọn núi đá vôi nhô lên trên một bãi cát ven biển, trên một diện tích khoảng 2 km² nằm cách trung tâm thành phố Đà Nẵng, Việt Nam khoảng 8 km về phía Đông Nam, ngay trên tuyến đường Đà Nẵng - Hội An; nay thuộc phường Ngũ Hành Sơn, thành phố Đà Nẵng.', 'verified', '2026-09-12 02:21:43.509374', '2026-09-11 19:20:07.470601');
INSERT INTO public.place_location VALUES ('3c1f73c0-538f-4214-8d03-c3e42c23a837', '9af558f7-f735-5381-9b00-8c3505e830e8', 'số 156 Trần Phú, phường Hải Châu', 'Hải Châu', NULL, 'Đà Nẵng', NULL, NULL, NULL, NULL, 'https://vi.wikipedia.org/wiki/Nh%C3%A0_th%E1%BB%9D_ch%C3%ADnh_t%C3%B2a_%C4%90%C3%A0_N%E1%BA%B5ng', NULL, 'Đà Nẵng toạ lạc tại số 156 Trần Phú, P. Hải Châu, Thành Phố Đà Nẵng, Việt Nam.', 'verified', '2026-09-12 02:21:43.511152', '2026-09-11 19:21:43.470506');


